-- Classic 1.60 (WoW Forever): SmartAI существ: недостающие касты в бою (UPDATE_IC -> CAST) и AIName=SmartAI у существ без скрипта
-- Источник: снифы официального сервера Classic (бета «актуал»), сборки 70245, 70291, 70338, 70425, 70450; сгенерировано ForeverSniffTools.
-- INSERT NOT EXISTS по ключу (entryorguid, source_type, id, link); UPDATE AIName только при пустом значении.
-- Повторный запуск безопасен (проверено прогоном дважды на копии снимка БД).

INSERT INTO `smart_scripts` (`entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`event_param_string`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`action_param7`,`action_param_string`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_param_string`,`target_x`,`target_y`,`target_z`,`target_o`,`comment`)
SELECT `entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`event_param_string`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`action_param7`,`action_param_string`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_param_string`,`target_x`,`target_y`,`target_z`,`target_o`,`comment`
FROM (
SELECT 1507 AS `entryorguid`, 0 AS `source_type`, 3 AS `id`, 0 AS `link`, '' AS `Difficulties`, 0 AS `event_type`, 0 AS `event_phase_mask`, 100 AS `event_chance`, 0 AS `event_flags`, 0 AS `event_param1`, 3253 AS `event_param2`, 1000 AS `event_param3`, 3626 AS `event_param4`, 0 AS `event_param5`, '' AS `event_param_string`, 11 AS `action_type`, 6136 AS `action_param1`, 0 AS `action_param2`, 0 AS `action_param3`, 0 AS `action_param4`, 0 AS `action_param5`, 0 AS `action_param6`, 0 AS `action_param7`, NULL AS `action_param_string`, 2 AS `target_type`, 0 AS `target_param1`, 0 AS `target_param2`, 0 AS `target_param3`, 0 AS `target_param4`, NULL AS `target_param_string`, 0.0 AS `target_x`, 0.0 AS `target_y`, 0.0 AS `target_z`, 0.0 AS `target_o`, 'Scarlet Initiate - In Combat - Cast \'Окоченение\' on Victim (sniff: 7 casts, 3 instances)' AS `comment`
) AS `v`
WHERE NOT EXISTS (SELECT 1 FROM `smart_scripts` AS `x` WHERE `x`.`entryorguid` = `v`.`entryorguid` AND `x`.`source_type` = `v`.`source_type` AND `x`.`id` = `v`.`id` AND `x`.`link` = `v`.`link`);
